#!/bin/sh
# Install the SilentGlass Home Assistant bridge (owner service). Feed to /bin/sh on stdin as root.
# Installs unconfigured: set it up from a phone (TV: Home > Info > Home Assistant). Inverse: ha-bridge-restore.sh
set -eu
H=/opt/usr/home/owner; UD=$H/.config/systemd/user; Q=/opt/usr/share/silentglass-ha; N=silentglass-ha.service
usr(){ env HOME=$H XDG_RUNTIME_DIR=/run/user/5001 DBUS_SESSION_BUS_ADDRESS=kernel:path=/sys/fs/kdbus/5001-user/bus systemctl --user "$@"; }
[ "$(id -u)" = 0 ]
LBL=$(chsmack $H | sed 's/.*access="//; s/".*//')
mkdir -p $Q; chown root:users $Q; chmod 755 $Q; chsmack -a User $Q
base64 -d <<'B64_EOF' | gzip -dc > "$Q/silentglass-ha.dll.new"

B64_EOF
[ "$(sha256sum "$Q/silentglass-ha.dll.new" | cut -d" " -f1)" = 4ca9a38722be09122d6b4460e96596c2dcfde84d709092995d9ee728875c7947 ]
chown root:users "$Q/silentglass-ha.dll.new"; chmod 644 "$Q/silentglass-ha.dll.new"; chsmack -a "User" "$Q/silentglass-ha.dll.new"; mv "$Q/silentglass-ha.dll.new" "$Q/silentglass-ha.dll"
base64 -d > "$Q/silentglass-ha.runtimeconfig.json.new" <<'B64_EOF'

B64_EOF
[ "$(sha256sum "$Q/silentglass-ha.runtimeconfig.json.new" | cut -d" " -f1)" = a0882085ebc8618322fb819cc0e92bac0499419af91124d05f6d27662818ea83 ]
chown root:users "$Q/silentglass-ha.runtimeconfig.json.new"; chmod 644 "$Q/silentglass-ha.runtimeconfig.json.new"; chsmack -a "User" "$Q/silentglass-ha.runtimeconfig.json.new"; mv "$Q/silentglass-ha.runtimeconfig.json.new" "$Q/silentglass-ha.runtimeconfig.json"
base64 -d > "$H/.config/silentglass-ha.conf.example.new" <<'B64_EOF'

B64_EOF
[ "$(sha256sum "$H/.config/silentglass-ha.conf.example.new" | cut -d" " -f1)" = 71b456d2b7ed533bb68f269ade4abfb0b98a674a5b82ef1a5701ed4731ca40d0 ]
chown owner:users "$H/.config/silentglass-ha.conf.example.new"; chmod 644 "$H/.config/silentglass-ha.conf.example.new"; chsmack -a "$LBL" "$H/.config/silentglass-ha.conf.example.new"; mv "$H/.config/silentglass-ha.conf.example.new" "$H/.config/silentglass-ha.conf.example"
base64 -d > "$UD/$N.new" <<'B64_EOF'

B64_EOF
[ "$(sha256sum "$UD/$N.new" | cut -d" " -f1)" = 5a4f420c5c7d7da61de2ce191ec0a5dd7a0e7263fb15f8c693a3056965f0bafb ]
chown owner:users "$UD/$N.new"; chmod 644 "$UD/$N.new"; chsmack -a "$LBL" "$UD/$N.new"; mv "$UD/$N.new" "$UD/$N"
ln -sf ../$N "$UD/default.target.wants/$N"; chown -h owner:users "$UD/default.target.wants/$N"
usr daemon-reload
usr restart $N; sleep 8; tail -n 4 /run/user/5001/silentglass-ha.log 2>/dev/null || true
echo "$N: $(usr is-enabled $N) $(usr is-active $N)"
echo 'HA BRIDGE INSTALLED'
